import React, { useEffect, useRef, useState } from "react";
import { attendanceAPI } from "./api_service";

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const overlayRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const canvasRef = useRef(document.createElement("canvas"));
  const processingRef = useRef(false);

  // anti double détection (par jour)
  const detectedTodayRef = useRef(new Set());

  const [results, setResults] = useState([]);
  const [capturedImage, setCapturedImage] = useState(null);
  const [autoMode, setAutoMode] = useState(true);

  // ===============================
  // BEEP SOUND
  // ===============================
  const playBeep = () => {
    const audio = new Audio(
      "https://actions.google.com/sounds/v1/alarms/beep_short.ogg"
    );
    audio.play();
  };

  // ===============================
  // START CAMERA
  // ===============================
  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            width: 1280,
            height: 720,
            facingMode: "user"
          },
          audio: false
        });

        streamRef.current = stream;
        videoRef.current.srcObject = stream;
      } catch (err) {
        console.error(err);
      }
    };

    startCamera();

    return () => {
      stopCamera();
    };
  }, []);

  // ===============================
  // AUTO DETECTION
  // ===============================
  useEffect(() => {
    if (!autoMode) return;

    intervalRef.current = setInterval(async () => {
      if (!videoRef.current) return;
      if (processingRef.current) return;

      if (videoRef.current.readyState !== 4) return;

      processingRef.current = true;

      try {
        const canvas = canvasRef.current;

        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;

        const ctx = canvas.getContext("2d");
        ctx.drawImage(videoRef.current, 0, 0);

        const image = canvas.toDataURL("image/jpeg", 0.6);
        setCapturedImage(image);

        const response = await attendanceAPI.recognize(image);
        const data = response?.data || {};

        if (!data.students) {
          processingRef.current = false;
          return;
        }

        setResults(data.students);

        drawBoxes(data.students);

        data.students.forEach(student => {
          if (!detectedTodayRef.current.has(student.name)) {

            detectedTodayRef.current.add(student.name);

            playBeep();

            addNotification(
              ` ${student.name} marqué présent`,
              "success"
            );
          }
        });

      } catch (err) {
        console.log(err);
      }

      processingRef.current = false;

    }, 1000);

    return () => clearInterval(intervalRef.current);

  }, [autoMode]);

  // ===============================
  // DRAW RECTANGLES
  // ===============================
  const drawBoxes = students => {
    const canvas = overlayRef.current;
    const ctx = canvas.getContext("2d");

    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    students.forEach(student => {
      const [x, y, w, h] = student.box;

      ctx.strokeStyle = "#22c55e";
      ctx.lineWidth = 3;
      ctx.strokeRect(x, y, w, h);

      ctx.fillStyle = "#22c55e";
      ctx.font = "16px Arial";
      ctx.fillText(
        `${student.name} ${(student.confidence * 100).toFixed(1)}%`,
        x,
        y - 8
      );
    });
  };

  // ===============================
  // STOP CAMERA
  // ===============================
  const stopCamera = () => {
    if (intervalRef.current) clearInterval(intervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    setAutoMode(false);
  };

  // ===============================
  // RENDER
  // ===============================
  return (
    <div style={styles.container}>

      <h2>Reconnaissance Faciale</h2>

      <div style={styles.videoWrapper}>
        <video
          ref={videoRef}
          autoPlay
          muted
          playsInline
          style={styles.video}
        />

        <canvas
          ref={overlayRef}
          style={styles.overlay}
        />
      </div>

      <div style={styles.controls}>
        <button onClick={() => setAutoMode(!autoMode)}>
          {autoMode ? "Pause" : "Start"}
        </button>

        <button onClick={stopCamera}>
          Stop Camera
        </button>
      </div>

      {results.map((student, i) => (
        <div key={i} style={styles.card}>

          <div style={styles.images}>

            <div>
              <h4>Capture</h4>
              <img
                src={capturedImage}
                style={styles.image}
              />
            </div>

            <div>
              <h4>Élève reconnu</h4>
              <img
                src={student.student_image}
                style={styles.image}
              />
            </div>

          </div>

          <div style={styles.present}>
             PRÉSENT
          </div>

          <div style={styles.info}>
            <p><b>Nom:</b> {student.name}</p>
            <p><b>Email:</b> {student.email}</p>
            <p><b>Confiance:</b> {(student.confidence*100).toFixed(1)}%</p>
          </div>

        </div>
      ))}

    </div>
  );
};

const styles = {

  container:{
    maxWidth:900,
    margin:"auto",
    padding:20
  },

  videoWrapper:{
    position:"relative"
  },

  video:{
    width:"100%",
    borderRadius:12
  },

  overlay:{
    position:"absolute",
    top:0,
    left:0,
    width:"100%",
    height:"100%"
  },

  controls:{
    marginTop:10,
    display:"flex",
    gap:10
  },

  card:{
    background:"#f8fafc",
    marginTop:15,
    padding:15,
    borderRadius:12
  },

  images:{
    display:"flex",
    gap:20
  },

  image:{
    width:260,
    borderRadius:8,
    border:"2px solid #ddd"
  },

  present:{
    background:"#16a34a",
    color:"white",
    padding:8,
    marginTop:10,
    borderRadius:6,
    textAlign:"center",
    fontWeight:"bold"
  },

  info:{
    marginTop:10
  }

};

export default CameraRecognition;
